from pathlib import Path
import json,html
root=Path(__file__).resolve().parents[1]
data=json.loads((root/'assets/catalog-snapshot.json').read_text())['tools']
configs=[
('video','AI video tools','AI 视频工具','Explore tools for generating clips, editing footage, and creating presenter videos.','探索短片生成、视频剪辑和数字人视频工具。','Choose a ten-second story. Compare motion, editing control, and export options before committing to a longer project.','从一个十秒钟的小故事开始，比较运动效果、编辑自由度和导出选项，再决定是否制作长片。','runway pika luma-dream-machine kling-ai sora pixverse hailuo-ai heygen synthesia descript capcut veed kapwing invideo-ai opusclip d-id','Can every tool generate video from text?','No. This pool includes generators, editors, clipping tools, and avatar tools. Check the introduction to find the right step in your workflow.','每个工具都支持文生视频吗？','不是。这里包含生成、剪辑、短视频切片和数字人工具，请根据产品介绍选择适合的环节。'),
('image','AI image tools','AI 图片工具','Discover tools for generating images, editing photos, and preparing visual assets.','发现图片生成、照片编辑和视觉素材处理工具。','Bring one photo or one visual idea. Compare detail, background handling, and how easily you can revise the result.','带上一张照片或一个视觉想法，比较细节、背景处理和修改结果的便利程度。','midjourney dall-e adobe-firefly ideogram leonardo-ai krea freepik-ai picsart photoroom remove-bg clipdrop','Are all tools in this pool image generators?','Some generate images, while others edit photos or remove backgrounds. Choose by the task you want to complete, rather than expecting every tool to do everything.','这里都是图片生成工具吗？','有些负责生成图片，有些负责修图或去背景。请按任务选择，每个工具的能力范围有所不同。'),
('coding','AI coding tools','AI 编程工具','Meet coding assistants, code review tools, and AI app builders for your next small project.','为下一个小项目发现编程助手、代码审查工具和 AI 应用搭建工具。','Try a tiny to-do list or a small bug fix. Review the generated changes and test the result before using it in a real project.','从待办清单或一个小错误开始，检查生成的改动并测试结果，再用于实际项目。','cursor github-copilot tabnine sourcegraph-cody aider coderabbit qodo blackbox-ai continue augment-code windsurf devin claude-code cline replit lovable v0 bolt firebase-studio emergent','Do I need to know how to code?','The pool mixes developer assistants with app builders. Some need an existing codebase; others accept a plain-language idea. Check setup requirements before starting.','需要会编程才能使用吗？','工具池同时包含开发助手和应用搭建工具。有些需要现成代码库，有些可以从自然语言想法开始，使用前请查看配置要求。'),
('presentation','AI presentation tools','AI PPT 工具','Find a tool to turn an outline into slides, refine layouts, or prepare a presentation.','发现把大纲变成幻灯片、调整版式和准备演示内容的工具。','Turn three weekend plans into five slides. Check narrative structure, editability, and export formats with your own content.','把三个周末安排做成五页演示，用自己的内容检查叙事结构、可编辑性和导出格式。','aippt plus-ai presentations-ai pitch canva-ai gamma beautiful-ai microsoft-copilot','Can I export every result to PowerPoint?','Export formats and editing features differ by tool and plan. Check PowerPoint or Google Slides support on the official website before making a full deck.','每个工具都支持导出 PowerPoint 吗？','导出格式和编辑功能因工具与套餐而异。制作完整演示前，请先在官网确认 PowerPoint 或 Google Slides 支持情况。')]
config={}
esc=lambda s:html.escape(s,quote=True)
head=(root/'index.html').read_text().split('<body>')[0].replace('<link rel="stylesheet" href="/assets/category-pages.css">','')
for key,en,zh,desc,descz,task,taskz,ids,q,a,qz,az in configs:
 slug='ai-'+key+'-tools'; members=ids.split(); tools=[t for t in data if t['slug'] in members]
 assert len(tools)==len(members),(key,set(members)-{t['slug'] for t in tools})
 config[slug]={'ids':members,'en':{'name':en,'description':desc,'title':f'Discover {en} — Random Tool Picker | RandomAI','headline':f'Which {en.replace("AI ","AI ")} will you discover?'},'zh':{'name':zh,'description':descz,'title':zh+'扭蛋机 — 随机发现好工具 | RandomAI','headline':'今天，会遇见什么 '+zh+'？'}}
 for lang in ['en','zh']:
  cn=lang=='zh'; path=('/zh/' if cn else '/')+slug+'/'; title=config[slug][lang]['title']; d=descz if cn else desc
  h=head.replace('<html lang="en">','<html lang="zh-CN">' if cn else '<html lang="en">')
  import re
  h=re.sub(r'<title>.*?</title>','<title>'+esc(title)+'</title>',h)
  h=re.sub(r'(<meta name="description" content=")[^"]*',lambda m:m[1]+esc(d),h)
  h=re.sub(r'(<meta (?:property="og:title"|name="twitter:title") content=")[^"]*',lambda m:m[1]+esc(title),h)
  h=re.sub(r'(<meta (?:property="og:description"|name="twitter:description") content=")[^"]*',lambda m:m[1]+esc(d),h)
  h=h.replace('https://www.randomai.top/"','https://www.randomai.top'+path+'"')
  h=h.replace('</head>',f'<link rel="alternate" hreflang="en" href="https://www.randomai.top/{slug}/"><link rel="alternate" hreflang="zh-CN" href="https://www.randomai.top/zh/{slug}/"><link rel="alternate" hreflang="x-default" href="https://www.randomai.top/{slug}/">\n<link rel="stylesheet" href="/assets/category-pages.css">\n</head>')
  nav='<nav class="category-nav" aria-label="'+('探索分类' if cn else 'Explore categories')+'"><h3 class="category-nav-heading">'+('探索其他主题扭蛋机' if cn else 'Explore more capsule machines')+'</h3>'+f'<a href="/">'+('全部 AI 工具' if cn else 'All AI tools')+'</a>'+''.join(f'<a href="'+('/zh/' if cn else '/')+'ai-'+k+'-tools/"'+(' aria-current="page"' if k==key else '')+'>'+esc(z if cn else e)+'</a>' for k,e,z,*_ in configs)+'</nav>'
  content=f'<section id="discovery-guide" aria-labelledby="category-title"><p class="guide-eyebrow">'+('主题扭蛋机' if cn else 'A CAPSULE FOR YOUR NEXT TASK')+f'</p><h2 id="category-title">{esc(zh if cn else en)}</h2><p class="guide-lead">{esc(d)}</p><div class="guide-how"><h3>'+('先玩一个小任务' if cn else 'Start with a small experiment')+f'</h3><p>{esc(taskz if cn else task)}</p></div><div class="guide-how"><h3>'+('怎么玩？' if cn else 'How does it work?')+'</h3><p>'+('投入免费灵感币，转动手柄，再打开扭蛋。这里只抽取本主题的工具，一轮内不重复；刷新页面或工具池更新后会重新洗牌。收起后可以点击已收集玩具，回看对应产品。' if cn else 'Insert a free coin, turn the crank, and open your capsule. Draws only use this topic’s pool, without repeats within a round. Reloading or a pool update reshuffles it. Tap a collected toy to revisit its tool.')+'</p></div><div class="guide-faq"><h3>'+('常见问题' if cn else 'Before you try')+f'</h3><details><summary>{esc(qz if cn else q)}</summary><div class="faq-answer"><p>{esc(az if cn else a)}</p></div></details><details><summary>'+('抽到的工具可以免费使用吗？' if cn else 'Are the tools free to use?')+'</summary><div class="faq-answer"><p>'+('扭蛋免费，但产品可能提供免费额度、试用或付费套餐，请以产品官网为准。' if cn else 'The capsule machine is free. Individual tools may offer free credits, trials, or paid plans; check the official website for current terms.')+'</p></div></details></div>'+nav+'</section>'
  scripts='\n'.join('<script src="'+s+'"></script>' for s in ['/assets/category-config.js','/assets/i18n.js?v=categories-4','/assets/catalog-snapshot.js','/assets/products.js?v=categories-4','/assets/vendor/colorfigures/gashapon.js','/assets/gashapon-app.js?v=categories-4'])
  dest=root/path.strip('/');dest.mkdir(parents=True,exist_ok=True);(dest/'index.html').write_text(h+'<body>'+content+scripts+'</body></html>\n')
(root/'assets/category-config.js').write_text('/* Reviewed topic membership. Extend these lists when approving new catalog tools. */\nwindow.RANDOMAI_TOPICS='+json.dumps(config,ensure_ascii=False)+';\nconst topicSlug=location.pathname.split("/").filter(Boolean).find(part=>window.RANDOMAI_TOPICS[part]);\nwindow.RANDOMAI_TOPIC=window.RANDOMAI_TOPICS[topicSlug];\nwindow.RANDOMAI_TOPIC_SLUG=topicSlug;\n')
